// Decade counter, period 10. Same as "mod 10" counter, but a separate
// register per stage (the long path -> lower Fmax).
module TopModule(input clk, input reset, output reg [3:0] q);
    reg [3:0] c1, c2, c3, c4;
    always @(posedge clk) begin
        if (reset) begin
            c1 <= 4'd0; c2 <= 4'd0; c3 <= 4'd0; c4 <= 4'd0;
        end else begin
            c1 <= c1 + 4'd1;
            if (c1 == 4'd9) begin c1 <= 4'd0; c2 <= c2 + 4'd1; end
            if (c2 == 4'd9) begin c2 <= 4'd0; c3 <= c3 + 4'd1; end
            if (c3 == 4'd9) begin c3 <= 4'd0; c4 <= c4 + 4'd1; end
        end
    end
    always @(posedge clk) q <= c4;
endmodule

